yA(a,b){return"\u041f\u0440\u043e\u043f\u043e\u0437\u0438\u0446\u0456\u044f "+a+" \u0456\u0437 "+b},
yB(a,b,c){return"\u0426\u044f \u043f\u043e\u0434\u0430\u0447\u0430 \u0432\u0438\u043a\u043e\u0440\u0438\u0441\u0442\u0430\u0454 \u0441\u043f\u0440\u043e\u0431\u0443 "+a+" \u0456\u0437 "+b+". \u041f\u0456\u0441\u043b\u044f \u043d\u0430\u0434\u0441\u0438\u043b\u0430\u043d\u043d\u044f \u0437\u0430\u043b\u0438\u0448\u0438\u0442\u044c\u0441\u044f "+c+" \u0441\u043f\u0440\u043e\u0431."},
gOM(){return"\u0421\u0442\u0440\u043e\u043a \u043f\u0443\u0431\u043b\u0456\u043a\u0430\u0446\u0456\u0457 \u0437\u0430\u043c\u043e\u0432\u043b\u0435\u043d\u043d\u044f"},
gOH(){return"1 \u043c\u0456\u0441\u044f\u0446\u044c"},
OG(a){return"\u0417\u0430\u043b\u0438\u0448\u0438\u0442\u0438 \u0437\u0430\u043c\u043e\u0432\u043b\u0435\u043d\u043d\u044f \u043e\u043f\u0443\u0431\u043b\u0456\u043a\u043e\u0432\u0430\u043d\u0438\u043c \u0434\u043e "+a+" \u0432\u043a\u043b\u044e\u0447\u043d\u043e."},
