OI(a){return"\u0417\u0430\u043b\u0438\u0448\u0438\u0442\u0438 \u0437\u0430\u043c\u043e\u0432\u043b\u0435\u043d\u043d\u044f \u043e\u043f\u0443\u0431\u043b\u0456\u043a\u043e\u0432\u0430\u043d\u0438\u043c \u0434\u043e "+a+" \u0432\u043a\u043b\u044e\u0447\u043d\u043e."},
gOL(){return"3 \u043c\u0456\u0441\u044f\u0446\u0456"},
